// ─────────────────────────────────────────────
// STEP 1 — PARSE & VALIDATE INCOMING PAYLOAD
// ─────────────────────────────────────────────
// Expected body: { projects: [...], githubToken: 'ghp_xxx', meta: {...} }

const raw = $input.first().json;
// n8n puts POST body under .body when webhook receives JSON
const body = raw.body || raw;

const scheduledRun = body?.scheduledRun === true;
const githubPushUpdate = body?.githubPushUpdate === true;

// If this is a scheduled run or GitHub push update, pass through with empty projects
if (scheduledRun || githubPushUpdate) {
  return [{
    json: {
      _valid: true,
      projects: [],
      githubToken: typeof body?.githubToken === 'string' ? body.githubToken.trim() : '',
      requestedAt: body?.meta?.requestedAt || new Date().toISOString(),
      projectCount: 0,
      scheduledRun,
      githubPushUpdate
    }
  }];
}

const projects = Array.isArray(body?.projects) ? body.projects : [];
const githubToken = typeof body?.githubToken === 'string' ? body.githubToken.trim() : '';
const requestedAt = body?.meta?.requestedAt || new Date().toISOString();

if (!projects.length) {
  return [{
    json: {
      _valid: false,
      error: 'No projects array in request body',
      success: false,
      summary: { total: 0, avgHealth: 0, totalMonthlyCost: 0, needsMigration: 0 },
      enrichedProjects: []
    }
  }];
}

return [{
  json: {
    _valid: true,
    projects,
    githubToken,
    requestedAt,
    projectCount: projects.length
  }
}];

// ─────────────────────────────────────────────────────────────────
// STEP 2 — GITHUB ENRICHMENT + HEALTH CALCULATION
// ─────────────────────────────────────────────────────────────────
// For each project with a GitHub repo URL, we:
//   1. Fetch repo metadata (stars, forks, open issues, language)
//   2. Fetch last commit date + message
//   3. Update lastActivity if commit is more recent
// Then calculate health scores and aggregate summary stats.
// ─────────────────────────────────────────────────────────────────

const { projects, githubToken, requestedAt, scheduledRun, githubPushUpdate } = $json;

// ── Early Exit for Scheduled/Push Runs or Empty Projects ────────
if (!projects || projects.length === 0) {
  return [{
    json: {
      success: true,
      scheduledRun: scheduledRun || false,
      githubPushUpdate: githubPushUpdate || false,
      note: scheduledRun ? 'Scheduled run - no projects to process' : (githubPushUpdate ? 'GitHub push update - no projects to process' : 'No projects provided'),
      summary: {
        total: 0,
        avgHealth: 0,
        totalMonthlyCost: 0,
        needsMigration: 0,
        activeCount: 0,
        blockedCount: 0,
        unhealthyCount: 0,
        githubEnriched: 0,
        enrichErrors: 0
      },
      enrichedProjects: [],
      criticalProjects: [],
      processedAt: new Date().toISOString(),
      requestedAt
    }
  }];
}

// ── Health Calculation (mirrors frontend logic exactly) ──────────
const calcHealth = (project, overrideActivity) => {
  const activity = overrideActivity || project.lastActivity;
  const days = activity
    ? Math.floor((Date.now() - new Date(activity)) / 86400000)
    : 999;

  let s = 100;
  if (days > 180)      s -= 40;
  else if (days > 90)  s -= 25;
  else if (days > 30)  s -= 10;

  s -= ((project.techDebt    || 3) - 1) * 8;
  if (project.status === 'Blocked')                          s -= 20;
  if (project.status === 'Archived' || project.status === 'Sunset') s -= 30;
  s += ((project.businessValue || 3) - 3) * 5;

  const auditPassed = Object.values(project.auditChecks || {}).filter(Boolean).length;
  s += auditPassed * 2;

  return Math.max(0, Math.min(100, Math.round(s)));
};

// ── GitHub Enrichment ────────────────────────────────────────────
const enrichedProjects = [];
let githubEnrichedCount = 0;
const errors = [];

for (const project of projects) {
  let githubData = project.githubData || null;
  let updatedActivity = project.lastActivity;

  if (project.repo && project.repo.includes('github.com') && githubToken) {
    const match = project.repo.match(/github\.com\/([^\/]+)\/([^\/]+)/);
    if (match) {
      const owner   = match[1];
      const repoRaw = match[2];
      const repo    = repoRaw.replace('.git', '').split('?')[0];

      const headers = {
        'Authorization': `token ${githubToken}`,
        'Accept':        'application/vnd.github.v3+json',
        'User-Agent':    'Portfolio-Command-Center/1.0'
      };

      try {
        // Throttle: 300ms between GitHub calls to respect rate limits
        await new Promise(r => setTimeout(r, 300));

        const [repoRes, commitsRes] = await Promise.all([
          fetch(`https://api.github.com/repos/${owner}/${repo}`,                   { headers }),
          fetch(`https://api.github.com/repos/${owner}/${repo}/commits?per_page=1`, { headers })
        ]);

        if (repoRes.ok) {
          const repoData    = await repoRes.json();
          const commitsData = commitsRes.ok ? await commitsRes.json() : [];

          const lastCommitObj = Array.isArray(commitsData) && commitsData[0]
            ? commitsData[0] : null;
          const lastCommit    = lastCommitObj?.commit?.committer?.date || null;
          const lastCommitMsg = lastCommitObj?.commit?.message?.split('\n')[0] || null;

          githubData = {
            stars:         repoData.stargazers_count  || 0,
            forks:         repoData.forks_count       || 0,
            openIssues:    repoData.open_issues_count || 0,
            lastCommit,
            lastCommitMsg,
            language:      repoData.language          || null,
            size:          repoData.size              || 0,
            defaultBranch: repoData.default_branch    || 'main',
            private:       repoData.private           || false,
            updatedAt:     repoData.updated_at        || null
          };

          // Update activity from commit if more recent than stored value
          if (lastCommit) {
            const commitDay = lastCommit.split('T')[0];
            if (!updatedActivity || commitDay > updatedActivity) {
              updatedActivity = commitDay;
            }
          }

          githubEnrichedCount++;
        } else {
          const errBody = await repoRes.text();
          errors.push({ project: project.name, status: repoRes.status, detail: errBody.slice(0, 100) });
        }
      } catch (err) {
        // Network or fetch error — keep existing data, don't abort
        errors.push({ project: project.name, error: err.message });
      }
    }
  }

  enrichedProjects.push({
    id:           project.id,
    githubData,
    lastActivity: updatedActivity
  });
}

// ── Build Enrichment Map ─────────────────────────────────────────
const enrichMap = Object.fromEntries(
  enrichedProjects.map(e => [e.id, e])
);

// ── Calculate Health for All Projects ───────────────────────────
const healthScores = projects.map(p => {
  const enriched          = enrichMap[p.id];
  const effectiveActivity = enriched?.lastActivity || p.lastActivity;
  return calcHealth(p, effectiveActivity);
});

const avgHealth = healthScores.length
  ? Math.round(healthScores.reduce((a, b) => a + b, 0) / healthScores.length)
  : 0;

// ── Identify Critical Projects (for optional Slack alert) ────────
const criticalProjects = projects
  .map((p, i) => ({ ...p, health: healthScores[i] }))
  .filter(p => p.health < 40 || p.status === 'Blocked')
  .map(p => ({ id: p.id, name: p.name, health: p.health, status: p.status, platform: p.platform }));

// ── Build Summary ────────────────────────────────────────────────
const summary = {
  total:             projects.length,
  avgHealth,
  totalMonthlyCost:  projects.reduce((s, p) => s + (p.monthlyCost || 0), 0),
  needsMigration:    projects.filter(p => p.platform === 'Base44' || p.platform === 'Bolt').length,
  activeCount:       projects.filter(p => p.status === 'Active').length,
  blockedCount:      projects.filter(p => p.status === 'Blocked').length,
  unhealthyCount:    healthScores.filter(h => h < 40).length,
  githubEnriched:    githubEnrichedCount,
  enrichErrors:      errors.length
};

return [{
  json: {
    success:         true,
    summary,
    enrichedProjects,
    criticalProjects,
    errors:          errors.length ? errors : undefined,
    processedAt:     new Date().toISOString(),
    requestedAt
  }
}];

