// ─────────────────────────────────────────────────────────────────
// VALIDATE AUTH & INPUT
// ─────────────────────────────────────────────────────────────────
// Validates:
//   1. API Key in X-API-Key header
//   2. Projects array structure
//   3. Required fields (id, name, status)
//   4. Data types and formats
// Returns validation result with detailed error messages
// ─────────────────────────────────────────────────────────────────

const raw = $input.first().json;
const body = raw.body || raw;
const headers = raw.headers || {};

// ── 1. Validate API Key ──────────────────────────────────────────
const apiKey = headers['x-api-key'] || headers['X-API-Key'];
const expectedApiKey = $env.PORTFOLIO_API_KEY || 'your-secret-api-key';

if (!apiKey) {
  return [{
    json: {
      valid: false,
      error: 'Missing API key',
      message: 'X-API-Key header is required',
      code: 'AUTH_MISSING'
    }
  }];
}

if (apiKey !== expectedApiKey) {
  return [{
    json: {
      valid: false,
      error: 'Invalid API key',
      message: 'The provided API key is not valid',
      code: 'AUTH_INVALID'
    }
  }];
}

// ── 2. Validate Projects Array ───────────────────────────────────
if (!body.projects) {
  return [{
    json: {
      valid: false,
      error: 'Missing projects',
      message: 'Request body must include a "projects" array',
      code: 'MISSING_PROJECTS'
    }
  }];
}

if (!Array.isArray(body.projects)) {
  return [{
    json: {
      valid: false,
      error: 'Invalid projects format',
      message: 'The "projects" field must be an array',
      code: 'INVALID_PROJECTS_TYPE'
    }
  }];
}

const projects = body.projects;

if (projects.length === 0) {
  return [{
    json: {
      valid: false,
      error: 'Empty projects array',
      message: 'At least one project is required',
      code: 'EMPTY_PROJECTS'
    }
  }];
}

// ── 3. Validate Required Fields & Data Types ─────────────────────
const requiredFields = ['id', 'name', 'status'];
const validStatuses = ['Active', 'Blocked', 'Archived', 'Sunset', 'Planning'];
const errors = [];

for (let i = 0; i < projects.length; i++) {
  const project = projects[i];
  const prefix = `Project[${i}]`;

  // Check required fields
  for (const field of requiredFields) {
    if (!project[field]) {
      errors.push(`${prefix}: Missing required field "${field}"`);
    }
  }

  // Validate data types
  if (project.id && typeof project.id !== 'string') {
    errors.push(`${prefix}: Field "id" must be a string`);
  }

  if (project.name && typeof project.name !== 'string') {
    errors.push(`${prefix}: Field "name" must be a string`);
  }

  if (project.status && !validStatuses.includes(project.status)) {
    errors.push(`${prefix}: Invalid status "${project.status}". Must be one of: ${validStatuses.join(', ')}`);
  }

  // Validate optional numeric fields
  if (project.monthlyCost !== undefined && typeof project.monthlyCost !== 'number') {
    errors.push(`${prefix}: Field "monthlyCost" must be a number`);
  }

  if (project.techDebt !== undefined && (typeof project.techDebt !== 'number' || project.techDebt < 1 || project.techDebt > 5)) {
    errors.push(`${prefix}: Field "techDebt" must be a number between 1 and 5`);
  }

  if (project.businessValue !== undefined && (typeof project.businessValue !== 'number' || project.businessValue < 1 || project.businessValue > 5)) {
    errors.push(`${prefix}: Field "businessValue" must be a number between 1 and 5`);
  }

  // Validate date format for lastActivity
  if (project.lastActivity && !/^\d{4}-\d{2}-\d{2}$/.test(project.lastActivity)) {
    errors.push(`${prefix}: Field "lastActivity" must be in YYYY-MM-DD format`);
  }

  // Validate repo URL format if provided
  if (project.repo && typeof project.repo === 'string' && !project.repo.includes('github.com')) {
    errors.push(`${prefix}: Field "repo" must be a valid GitHub URL`);
  }
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: 'Validation failed',
      message: `Found ${errors.length} validation error(s)`,
      code: 'VALIDATION_FAILED',
      details: errors
    }
  }];
}

// ── 4. Validation Passed ─────────────────────────────────────────
return [{
  json: {
    valid: true,
    projects,
    githubToken: body.githubToken || '',
    requestedAt: body.meta?.requestedAt || new Date().toISOString(),
    projectCount: projects.length,
    message: 'Validation successful'
  }
}];

// ─────────────────────────────────────────────────────────────────
// PARALLEL GITHUB ENRICHMENT (Per-Item Mode)
// ─────────────────────────────────────────────────────────────────
// For each project in the batch:
//   1. Check cache for recent data (< 1 hour old)
//   2. If cache miss or stale, fetch from GitHub API
//   3. Handle rate limits via X-RateLimit-Remaining header
//   4. Retry failed requests with exponential backoff (3 attempts)
//   5. Timeout protection: 10s per request
//   6. Return enriched project with comprehensive error context
// ─────────────────────────────────────────────────────────────────

const project = $json;
const githubToken = $('Parse Input').item.json.githubToken;

// ── Helper: Exponential Backoff Retry ────────────────────────────
const fetchWithRetry = async (url, options, maxRetries = 3) => {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 10000); // 10s timeout

      const response = await fetch(url, { ...options, signal: controller.signal });
      clearTimeout(timeoutId);

      // Check rate limit from response headers
      const remaining = parseInt(response.headers.get('X-RateLimit-Remaining') || '999', 10);
      if (remaining < 10) {
        const resetTime = parseInt(response.headers.get('X-RateLimit-Reset') || '0', 10);
        const waitMs = Math.max(0, (resetTime * 1000) - Date.now());
        if (waitMs > 0 && waitMs < 60000) { // Wait max 1 minute
          await new Promise(r => setTimeout(r, waitMs));
        }
      }

      if (response.ok) {
        return { success: true, data: await response.json(), status: response.status };
      }

      // Handle rate limit (403 or 429)
      if (response.status === 403 || response.status === 429) {
        const resetTime = parseInt(response.headers.get('X-RateLimit-Reset') || '0', 10);
        const waitMs = Math.max(1000, (resetTime * 1000) - Date.now());
        if (attempt < maxRetries && waitMs < 60000) {
          await new Promise(r => setTimeout(r, Math.min(waitMs, 5000)));
          continue;
        }
      }

      // Other errors: return with context
      return {
        success: false,
        status: response.status,
        error: await response.text(),
        attempt
      };

    } catch (err) {
      // Timeout or network error
      if (attempt < maxRetries) {
        const backoffMs = Math.min(1000 * Math.pow(2, attempt - 1), 5000);
        await new Promise(r => setTimeout(r, backoffMs));
        continue;
      }
      return {
        success: false,
        error: err.message,
        timeout: err.name === 'AbortError',
        attempt
      };
    }
  }

  return { success: false, error: 'Max retries exceeded', attempt: maxRetries };
};

// ── Early Exit: No GitHub Repo ───────────────────────────────────
if (!project.repo || !project.repo.includes('github.com')) {
  return {
    json: {
      ...project,
      githubData: null,
      enrichmentStatus: 'skipped',
      enrichmentReason: 'No GitHub repo URL'
    }
  };
}

// ── Parse GitHub Owner/Repo ──────────────────────────────────────
const match = project.repo.match(/github\.com\/([^\/]+)\/([^\/]+)/);
if (!match) {
  return {
    json: {
      ...project,
      githubData: null,
      enrichmentStatus: 'error',
      enrichmentError: {
        message: 'Invalid GitHub URL format',
        repo: project.repo,
        timestamp: new Date().toISOString()
      }
    }
  };
}

const owner = match[1];
const repoRaw = match[2];
const repo = repoRaw.replace('.git', '').split('?')[0];

// ── Check Cache (from previous node) ────────────────────────────
const cacheData = $('Check GitHub Cache').all().find(
  c => c.json.projectId === project.id
);

const cacheAge = cacheData?.json.cachedAt
  ? (Date.now() - new Date(cacheData.json.cachedAt).getTime()) / 1000 / 60
  : 999;

if (cacheData && cacheAge < 60) {
  // Cache hit: use cached data
  return {
    json: {
      ...project,
      githubData: cacheData.json.githubData,
      lastActivity: cacheData.json.lastActivity || project.lastActivity,
      enrichmentStatus: 'cached',
      cacheAge: Math.round(cacheAge)
    }
  };
}

// ── Fetch from GitHub API ────────────────────────────────────────
if (!githubToken) {
  return {
    json: {
      ...project,
      githubData: null,
      enrichmentStatus: 'error',
      enrichmentError: {
        message: 'GitHub token not provided',
        timestamp: new Date().toISOString()
      }
    }
  };
}

const headers = {
  'Authorization': `token ${githubToken}`,
  'Accept': 'application/vnd.github.v3+json',
  'User-Agent': 'Portfolio-Command-Center/1.0'
};

const baseUrl = `https://api.github.com/repos/${owner}/${repo}`;

// Parallel fetch: repo metadata + recent commits
const [repoResult, commitsResult] = await Promise.all([
  fetchWithRetry(baseUrl, { headers }),
  fetchWithRetry(`${baseUrl}/commits?per_page=1`, { headers })
]);

// ── Handle Errors ────────────────────────────────────────────────
if (!repoResult.success) {
  return {
    json: {
      ...project,
      githubData: null,
      enrichmentStatus: 'error',
      enrichmentError: {
        projectName: project.name,
        repoUrl: project.repo,
        httpStatus: repoResult.status || null,
        message: repoResult.error || 'Unknown error',
        timeout: repoResult.timeout || false,
        attempts: repoResult.attempt,
        timestamp: new Date().toISOString()
      }
    }
  };
}

// ── Build GitHub Data ────────────────────────────────────────────
const repoData = repoResult.data;
const commitsData = commitsResult.success ? commitsResult.data : [];

const lastCommitObj = Array.isArray(commitsData) && commitsData[0]
  ? commitsData[0]
  : null;

const lastCommit = lastCommitObj?.commit?.committer?.date || null;
const lastCommitMsg = lastCommitObj?.commit?.message?.split('\n')[0] || null;

const githubData = {
  stars: repoData.stargazers_count || 0,
  forks: repoData.forks_count || 0,
  openIssues: repoData.open_issues_count || 0,
  lastCommit,
  lastCommitMsg,
  language: repoData.language || null,
  size: repoData.size || 0,
  defaultBranch: repoData.default_branch || 'main',
  private: repoData.private || false,
  updatedAt: repoData.updated_at || null
};

// Update lastActivity if commit is more recent
let updatedActivity = project.lastActivity;
if (lastCommit) {
  const commitDay = lastCommit.split('T')[0];
  if (!updatedActivity || commitDay > updatedActivity) {
    updatedActivity = commitDay;
  }
}

return {
  json: {
    ...project,
    githubData,
    lastActivity: updatedActivity,
    enrichmentStatus: 'success',
    enrichedAt: new Date().toISOString()
  }
};

// ─────────────────────────────────────────────────────────────────
// CALCULATE HEALTH & BREAKDOWN
// ─────────────────────────────────────────────────────────────────
// For each enriched project:
//   1. Calculate health score with detailed component breakdown
//   2. Track activity score, tech debt impact, status penalty, etc.
//   3. Aggregate summary statistics across all projects
//   4. Identify critical projects requiring attention
// ─────────────────────────────────────────────────────────────────

const projects = $input.all().map(item => item.json);

if (!projects || projects.length === 0) {
  return [{
    json: {
      success: true,
      summary: {
        total: 0,
        avgHealth: 0,
        totalMonthlyCost: 0,
        needsMigration: 0,
        activeCount: 0,
        blockedCount: 0,
        unhealthyCount: 0,
        avgActivityScore: 0,
        avgTechDebtImpact: 0,
        avgBusinessValueBonus: 0
      },
      projectsWithHealth: [],
      criticalProjects: [],
      processedAt: new Date().toISOString()
    }
  }];
}

// ── Health Calculation with Detailed Breakdown ───────────────────
const calculateHealthBreakdown = (project) => {
  const activity = project.lastActivity;
  const days = activity
    ? Math.floor((Date.now() - new Date(activity)) / 86400000)
    : 999;

  // Start with base score
  let baseScore = 100;
  let activityScore = 0;
  let techDebtImpact = 0;
  let statusPenalty = 0;
  let businessValueBonus = 0;
  let auditScore = 0;

  // Activity scoring
  if (days > 180) {
    activityScore = -40;
  } else if (days > 90) {
    activityScore = -25;
  } else if (days > 30) {
    activityScore = -10;
  } else {
    activityScore = 0;
  }

  // Tech debt impact
  const techDebt = project.techDebt || 3;
  techDebtImpact = -((techDebt - 1) * 8);

  // Status penalty
  if (project.status === 'Blocked') {
    statusPenalty = -20;
  } else if (project.status === 'Archived' || project.status === 'Sunset') {
    statusPenalty = -30;
  }

  // Business value bonus
  const businessValue = project.businessValue || 3;
  businessValueBonus = (businessValue - 3) * 5;

  // Audit checks bonus
  const auditPassed = Object.values(project.auditChecks || {}).filter(Boolean).length;
  auditScore = auditPassed * 2;

  // Calculate final health
  const finalHealth = Math.max(0, Math.min(100, Math.round(
    baseScore + activityScore + techDebtImpact + statusPenalty + businessValueBonus + auditScore
  )));

  return {
    health: finalHealth,
    breakdown: {
      baseScore,
      activityScore,
      activityDays: days,
      techDebtImpact,
      techDebtLevel: techDebt,
      statusPenalty,
      businessValueBonus,
      businessValueLevel: businessValue,
      auditScore,
      auditChecksPassed: auditPassed
    }
  };
};

// ── Calculate Health for All Projects ────────────────────────────
const projectsWithHealth = projects.map(project => {
  const { health, breakdown } = calculateHealthBreakdown(project);
  return {
    ...project,
    health,
    healthBreakdown: breakdown
  };
});

// ── Aggregate Summary Statistics ─────────────────────────────────
const totalHealth = projectsWithHealth.reduce((sum, p) => sum + p.health, 0);
const avgHealth = Math.round(totalHealth / projectsWithHealth.length);

const totalActivityScore = projectsWithHealth.reduce((sum, p) => sum + p.healthBreakdown.activityScore, 0);
const avgActivityScore = Math.round(totalActivityScore / projectsWithHealth.length);

const totalTechDebtImpact = projectsWithHealth.reduce((sum, p) => sum + p.healthBreakdown.techDebtImpact, 0);
const avgTechDebtImpact = Math.round(totalTechDebtImpact / projectsWithHealth.length);

const totalBusinessValueBonus = projectsWithHealth.reduce((sum, p) => sum + p.healthBreakdown.businessValueBonus, 0);
const avgBusinessValueBonus = Math.round(totalBusinessValueBonus / projectsWithHealth.length);

const summary = {
  total: projectsWithHealth.length,
  avgHealth,
  totalMonthlyCost: projectsWithHealth.reduce((sum, p) => sum + (p.monthlyCost || 0), 0),
  needsMigration: projectsWithHealth.filter(p => p.platform === 'Base44' || p.platform === 'Bolt').length,
  activeCount: projectsWithHealth.filter(p => p.status === 'Active').length,
  blockedCount: projectsWithHealth.filter(p => p.status === 'Blocked').length,
  unhealthyCount: projectsWithHealth.filter(p => p.health < 40).length,
  avgActivityScore,
  avgTechDebtImpact,
  avgBusinessValueBonus,
  healthDistribution: {
    excellent: projectsWithHealth.filter(p => p.health >= 80).length,
    good: projectsWithHealth.filter(p => p.health >= 60 && p.health < 80).length,
    fair: projectsWithHealth.filter(p => p.health >= 40 && p.health < 60).length,
    poor: projectsWithHealth.filter(p => p.health < 40).length
  }
};

// ── Identify Critical Projects ───────────────────────────────────
const criticalProjects = projectsWithHealth
  .filter(p => p.health < 40 || p.status === 'Blocked')
  .map(p => ({
    id: p.id,
    name: p.name,
    health: p.health,
    status: p.status,
    platform: p.platform,
    breakdown: p.healthBreakdown
  }))
  .sort((a, b) => a.health - b.health);

return [{
  json: {
    success: true,
    summary,
    projectsWithHealth,
    criticalProjects,
    processedAt: new Date().toISOString()
  }
}];

// ─────────────────────────────────────────────────────────────────
// BUILD DAILY DIGEST
// ─────────────────────────────────────────────────────────────────
// Extract summary fields from HTTP response and build digest text
// ─────────────────────────────────────────────────────────────────

const response = $input.first().json;
const summary = response.summary || {};

// Extract summary fields
const total = summary.total || 0;
const avgHealth = summary.avgHealth || 0;
const blockedCount = summary.blockedCount || 0;
const unhealthyCount = summary.unhealthyCount || 0;
const totalMonthlyCost = summary.totalMonthlyCost || 0;
const needsMigration = summary.needsMigration || 0;

// Calculate health status
let healthStatus;
if (avgHealth >= 70) {
  healthStatus = 'Healthy';
} else if (avgHealth >= 40) {
  healthStatus = 'Needs Attention';
} else {
  healthStatus = 'Critical';
}

// Build digest text
const digestText = `Portfolio Health Report

Overall Status: ${healthStatus}
Average Health Score: ${avgHealth}/100

Projects Overview:
• Total Projects: ${total}
• Blocked Projects: ${blockedCount}
• Unhealthy Projects: ${unhealthyCount}
• Projects Needing Migration: ${needsMigration}
• Total Monthly Cost: $${totalMonthlyCost.toFixed(2)}

Generated: ${new Date().toISOString()}`;

return [{
  json: {
    digestText,
    healthStatus,
    summary: {
      total,
      avgHealth,
      blockedCount,
      unhealthyCount,
      totalMonthlyCost,
      needsMigration
    }
  }
}];

