const body = $json.body || $json;

// Extract repository information
const repoFullName = body.repository?.full_name || null;
const repoUrl = body.repository?.html_url || null;

// Extract branch from ref (e.g., 'refs/heads/main' -> 'main')
const branch = body.ref ? body.ref.replace('refs/heads/', '') : null;

// Extract commit information
const commitCount = Array.isArray(body.commits) ? body.commits.length : 0;

// Extract latest commit details
const latestCommit = body.head_commit ? {
  sha: body.head_commit.id || null,
  message: body.head_commit.message || null,
  timestamp: body.head_commit.timestamp || null
} : null;

return [{
  json: {
    repoFullName,
    repoUrl,
    branch,
    commitCount,
    latestCommit
  }
}];
